<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { JIRAI_EMOTIONS, RIG_V3_RULES, VISEMES, sampleJirai, type JiraiEmotion, type Viseme } from './jiraiRig'
const now=ref(0),fps=ref(60),speaking=ref(false),autoViseme=ref(true),talkLevel=ref(.42),showReference=ref(false)
const fromEmotion=ref<JiraiEmotion>('neutral'),toEmotion=ref<JiraiEmotion>('neutral'),emotionProgress=ref(1)
const fromViseme=ref<Viseme>('REST'),toViseme=ref<Viseme>('REST'),visemeProgress=ref(1)
let emotionStarted=0,visemeStarted=0,raf=0,last=performance.now(),frames=0,fpsSince=last,lastAutoSlot=-1
const emotionMs=RIG_V3_RULES.emotionTransitionMs,visemeMs=RIG_V3_RULES.visemeGateMs
const phraseTrack:Viseme[]=['REST','A','A','E','I','REST','O','O','U','E','REST','SMILE','A','I','O','REST']
const frame=computed(()=>sampleJirai({t:now.value,fromEmotion:fromEmotion.value,toEmotion:toEmotion.value,emotionProgress:emotionProgress.value,speaking:speaking.value,fromViseme:fromViseme.value,toViseme:toViseme.value,visemeProgress:visemeProgress.value,talkLevel:talkLevel.value}))
function setEmotion(next:JiraiEmotion){if(next===toEmotion.value&&emotionProgress.value>=1)return;const effective=emotionProgress.value<.5?fromEmotion.value:toEmotion.value;fromEmotion.value=effective;toEmotion.value=next;emotionProgress.value=0;emotionStarted=performance.now()}
function setViseme(next:Viseme){if(next===toViseme.value&&visemeProgress.value>=1)return;const effective=visemeProgress.value<.5?fromViseme.value:toViseme.value;fromViseme.value=effective;toViseme.value=next;visemeProgress.value=0;visemeStarted=performance.now()}
function startSpeaking(){speaking.value=true;setEmotion('neutral');setViseme('REST')}
function stopSpeaking(){speaking.value=false;setViseme('REST')}
function tick(ms:number){const dt=Math.min((ms-last)/1000,.05);last=ms;now.value+=dt;emotionProgress.value=Math.min(1,(ms-emotionStarted)/emotionMs);visemeProgress.value=Math.min(1,(ms-visemeStarted)/visemeMs);if(speaking.value&&autoViseme.value){const slot=Math.floor(now.value/.13);if(slot!==lastAutoSlot){lastAutoSlot=slot;setViseme(phraseTrack[slot%phraseTrack.length])}const envelope=.14+Math.abs(Math.sin(now.value*7.2)*Math.sin(now.value*2.15))*.78;talkLevel.value=envelope;if(envelope<.18)setViseme('REST')}frames++;if(ms-fpsSince>=500){fps.value=Math.round(frames*1000/(ms-fpsSince));frames=0;fpsSince=ms}raf=requestAnimationFrame(tick)}
function playDemo(){stopSpeaking();setEmotion('neutral');const seq:Array<[number,()=>void]>=[[700,()=>setEmotion('happy')],[1900,()=>setEmotion('wink')],[2950,()=>setEmotion('surprised')],[4050,()=>setEmotion('sad')],[5250,()=>setEmotion('annoyed')],[6450,()=>setEmotion('sleepy')],[7600,()=>setEmotion('excited')],[8750,()=>startSpeaking()],[11600,()=>{stopSpeaking();setEmotion('neutral')}]];for(const[d,fn]of seq)window.setTimeout(fn,d)}
onMounted(()=>{last=performance.now();fpsSince=last;emotionStarted=last-emotionMs;visemeStarted=last-visemeMs;raf=requestAnimationFrame(tick)});onBeforeUnmount(()=>cancelAnimationFrame(raf))
</script>
<template><main class="app-shell"><section class="hero-panel"><header class="topbar"><div><p class="eyebrow">NE5 DESKPET NEO / JIRAI CUTOUT RIG V3</p><h1>Part-rig Character Simulator</h1></div><div class="metrics"><span><i class="dot"></i>{{fps}} FPS</span><span>No raster morph</span><span>1:1 sprite atlas</span></div></header><div class="stage jirai-stage"><div class="character-frame"><svg class="rig-canvas" viewBox="0 0 351 345" :aria-label="frame.statusLabel"><defs><clipPath v-for="(eye,i) in frame.eyes" :id="`eyeClip${i}`" :key="`ec-${i}`"><rect :x="eye.x-eye.rect.w/2-4" :y="eye.y-eye.rect.h/2+eye.rect.h*(1-eye.reveal)/2-2" :width="eye.rect.w+8" :height="Math.max(1,eye.rect.h*eye.reveal+4)"/></clipPath><clipPath v-for="(mouth,i) in frame.mouthSprites" :id="`mouthClip${i}`" :key="`mc-${i}`"><rect :x="179-mouth.rect.w/2-3" :y="220-mouth.rect.h/2+mouth.rect.h*(1-mouth.reveal)/2-2" :width="mouth.rect.w+6" :height="Math.max(1,mouth.rect.h*mouth.reveal+4)"/></clipPath></defs><g :transform="`translate(0 ${frame.rootY}) rotate(${frame.rootRotation} 176 180)`"><image :href="frame.baseSrc" x="0" y="0" width="351" height="345"/><g class="brows"><path :d="frame.browLeft"/><path :d="frame.browRight"/></g><g v-for="(eye,i) in frame.eyes" :key="`eye-${i}`" :transform="`rotate(${eye.rotation} ${eye.x} ${eye.y})`"><svg :x="eye.x-eye.rect.w/2" :y="eye.y-eye.rect.h/2" :width="eye.rect.w" :height="eye.rect.h" :viewBox="`${eye.rect.x} ${eye.rect.y} ${eye.rect.w} ${eye.rect.h}`" preserveAspectRatio="none" :clip-path="`url(#eyeClip${i})`"><image :href="frame.atlasSrc" x="0" y="0" width="256" height="331"/></svg><svg :x="eye.x-eye.closedRect.w/2" :y="eye.y-eye.closedRect.h/2" :width="eye.closedRect.w" :height="eye.closedRect.h" :viewBox="`${eye.closedRect.x} ${eye.closedRect.y} ${eye.closedRect.w} ${eye.closedRect.h}`" preserveAspectRatio="none" :opacity="eye.closedOpacity"><image :href="frame.atlasSrc" x="0" y="0" width="256" height="331"/></svg></g><path v-if="frame.mouthVectorPath&&frame.mouthVectorVisible" :d="frame.mouthVectorPath" class="rig-mouth-line"/><svg v-for="(mouth,i) in frame.mouthSprites" :key="`mouth-${i}`" :x="179-mouth.rect.w/2" :y="220-mouth.rect.h/2" :width="mouth.rect.w" :height="mouth.rect.h" :viewBox="`${mouth.rect.x} ${mouth.rect.y} ${mouth.rect.w} ${mouth.rect.h}`" preserveAspectRatio="none" :clip-path="`url(#mouthClip${i})`"><image :href="frame.atlasSrc" x="0" y="0" width="256" height="331"/></svg><svg v-for="(gesture,i) in frame.gestures" :key="`gesture-${i}`" :x="gesture.x-gesture.rect.w/2" :y="gesture.y-gesture.rect.h/2+gesture.offsetY" :width="gesture.rect.w" :height="gesture.rect.h" :viewBox="`${gesture.rect.x} ${gesture.rect.y} ${gesture.rect.w} ${gesture.rect.h}`" preserveAspectRatio="none"><image :href="frame.atlasSrc" x="0" y="0" width="256" height="331"/></svg></g></svg><img v-if="showReference" class="reference-overlay" :src="frame.referenceSrc" alt="target reference"/></div><div class="state-card"><span>CUTOUT OUTPUT</span><strong>{{frame.statusLabel}}</strong><small>Raster parts are cropped from one 1:1 atlas; no eye or mouth bitmap is mesh-morphed.</small></div></div></section><aside class="control-panel"><div class="panel-heading"><div><p class="eyebrow">RIG V3 CONTROLS</p><h2>Natural expression transition</h2></div><button class="primary" @click="playDemo">Run transition demo</button></div><section class="control-section"><div class="section-title"><span>01</span><h3>Reference expressions</h3></div><div class="chip-grid emotion-grid"><button v-for="e in JIRAI_EMOTIONS" :key="e" :class="{active:toEmotion===e&&!speaking}" @click="speaking=false;setEmotion(e)">{{e}}</button></div><div class="progress-note">Transition {{Math.round(emotionProgress*100)}}% · {{emotionMs}} ms</div></section><section class="control-section"><div class="section-title"><span>02</span><h3>Speech / viseme</h3></div><div class="renderer-dock"><button :class="{active:!speaking}" @click="stopSpeaking">Expression</button><button :class="{active:speaking}" @click="startSpeaking">Speaking</button></div><div class="chip-grid viseme-grid"><button v-for="v in VISEMES" :key="v" :disabled="autoViseme" :class="{active:toViseme===v&&speaking}" @click="speaking=true;setViseme(v)">{{v}}</button></div><label class="slider-row"><span>Amplitude <b>{{talkLevel.toFixed(2)}}</b></span><input v-model.number="talkLevel" :disabled="autoViseme" type="range" min="0" max="1" step=".01"/></label><label class="toggle"><input v-model="autoViseme" type="checkbox"/>Demo phoneme/viseme timeline</label></section><section class="control-section"><div class="section-title"><span>03</span><h3>Reference QA</h3></div><label class="toggle"><input v-model="showReference" type="checkbox"/>Overlay target reference PNG</label><p class="qa-copy">Overlay is QA-only. Runtime is a clean reference base plus cropped cutout parts.</p></section><section class="notes"><p><strong>No raster mesh morph.</strong> Neutral→happy closes the open-eye artwork by clipping, swaps to the happy-eye crop near maximum occlusion, then reveals it. Simple mouth/brow strokes interpolate control points; detailed mouths use discrete atlas sprites through a short REST gate.</p><p>The final TTS integration should provide phoneme/viseme timestamps. Auto mode is a deterministic preview timeline, not random amplitude-driven mouth selection.</p></section></aside></main></template>
